"use client";

import { useEffect, useId, useRef, useState, type ReactNode } from "react";
import { FileSearch, RefreshCw } from "lucide-react";
import { useLanguage } from "@/hooks/use-language";
import { cn } from "@/lib/utils";
import { Alert } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

export type RecordDetailMetadata = {
  id: string;
  label: ReactNode;
  value: ReactNode;
  icon?: ReactNode;
};

export type RecordDetailTab = {
  value: string;
  label: ReactNode;
  content: ReactNode;
  icon?: ReactNode;
  count?: number;
  disabled?: boolean;
  keepMounted?: boolean;
};

export type RecordDetailLabels = {
  loading: string;
  refreshing: string;
  errorTitle: string;
  retry: string;
  retryError: string;
  notFoundTitle: string;
  notFoundDescription: string;
  tabs: string;
};

export type GenericRecordDetailProps = {
  title: ReactNode;
  subtitle?: ReactNode;
  eyebrow?: ReactNode;
  avatar?: ReactNode;
  status?: ReactNode;
  metadata?: readonly RecordDetailMetadata[];
  actions?: ReactNode;
  backAction?: ReactNode;
  tabs?: readonly RecordDetailTab[];
  activeTab?: string;
  defaultTab?: string;
  onTabChange?: (value: string) => void;
  children?: ReactNode;
  relatedContent?: ReactNode;
  loading?: boolean;
  error?: string | null;
  onRetry?: () => void | Promise<void>;
  notFound?: boolean;
  notFoundAction?: ReactNode;
  labels?: Partial<RecordDetailLabels>;
  className?: string;
};

/** Presentation and UI state only. Data, permissions and mutations stay with the caller. */
export function GenericRecordDetail({
  title,
  subtitle,
  eyebrow,
  avatar,
  status,
  metadata = [],
  actions,
  backAction,
  tabs = [],
  activeTab,
  defaultTab,
  onTabChange,
  children,
  relatedContent,
  loading = false,
  error,
  onRetry,
  notFound = false,
  notFoundAction,
  labels,
  className,
}: GenericRecordDetailProps) {
  const { l } = useLanguage();
  const headingId = useId();
  const retryPending = useRef(false);
  const [retrying, setRetrying] = useState(false);
  const [retryError, setRetryError] = useState<string | null>(null);
  useEffect(() => setRetryError(null), [error]);
  const copy: RecordDetailLabels = {
    loading: l("Loading record…", "Cargando registro…"),
    refreshing: l("Updating record…", "Actualizando registro…"),
    errorTitle: l("Something needs attention", "Algo necesita atención"),
    retry: l("Try again", "Intentar de nuevo"),
    retryError: l(
      "The record could not be loaded. Please try again.",
      "No se pudo cargar el registro. Intenta de nuevo.",
    ),
    notFoundTitle: l("Record not found", "Registro no encontrado"),
    notFoundDescription: l(
      "This record may have been removed, or you may not have access to it.",
      "Es posible que este registro se haya eliminado o que no tengas acceso.",
    ),
    tabs: l("Record sections", "Secciones del registro"),
    ...labels,
  };
  const hasContent =
    children != null ||
    tabs.length > 0 ||
    metadata.length > 0 ||
    avatar != null;
  const initialLoading = loading && !hasContent;
  const missing = notFound && !loading;
  const problem = retryError || error;
  const firstTab = tabs.find((tab) => !tab.disabled)?.value;
  const initialTab = tabs.some(
    (tab) => tab.value === defaultTab && !tab.disabled,
  )
    ? defaultTab
    : firstTab;
  const selectedTab =
    activeTab === undefined
      ? undefined
      : tabs.some((tab) => tab.value === activeTab && !tab.disabled)
        ? activeTab
        : firstTab;

  const retry = async () => {
    if (!onRetry || retryPending.current || loading) return;
    retryPending.current = true;
    setRetrying(true);
    setRetryError(null);
    try {
      await onRetry();
    } catch (cause) {
      setRetryError(
        cause instanceof Error && cause.message
          ? cause.message
          : copy.retryError,
      );
    } finally {
      retryPending.current = false;
      setRetrying(false);
    }
  };

  return (
    <section
      aria-labelledby={headingId}
      aria-busy={loading || retrying}
      className={cn("grid min-w-0 gap-5 sm:gap-6", className)}
      data-slot="record-detail"
    >
      {backAction && <div className="flex min-w-0">{backAction}</div>}
      {initialLoading ? (
        <Card appearance="flat" className="p-5 sm:p-7">
          <h1 id={headingId} className="sr-only">
            {copy.loading}
          </h1>
          <p role="status" className="mb-5 text-sm text-muted-foreground">
            {copy.loading}
          </p>
          <div className="flex items-center gap-4">
            <Skeleton className="size-16 shrink-0 rounded-2xl" />
            <div className="grid w-full max-w-md gap-3">
              <Skeleton className="h-7 w-3/4" />
              <Skeleton className="h-4 w-full" />
            </div>
          </div>
          <div className="mt-8 grid gap-4 sm:grid-cols-3">
            {[0, 1, 2].map((item) => (
              <Skeleton key={item} className="h-24" />
            ))}
          </div>
        </Card>
      ) : missing ? (
        <Card
          appearance="flat"
          className="flex flex-col items-center gap-4 px-5 py-14 text-center"
        >
          <span
            aria-hidden="true"
            className="flex size-12 items-center justify-center rounded-2xl border border-border bg-surface-subtle text-muted-foreground"
          >
            <FileSearch className="size-5" />
          </span>
          <h1 id={headingId} className="text-xl font-semibold tracking-tight">
            {copy.notFoundTitle}
          </h1>
          <p className="max-w-md text-sm leading-7 text-muted-foreground">
            {copy.notFoundDescription}
          </p>
          {notFoundAction && <div className="mt-2">{notFoundAction}</div>}
        </Card>
      ) : (
        <Card appearance="gradient" className="overflow-hidden p-5 sm:p-7">
          {eyebrow && (
            <p className="mb-5 text-[11px] font-semibold tracking-[.1em] text-primary uppercase">
              {eyebrow}
            </p>
          )}
          <div className="flex min-w-0 flex-col gap-5 sm:flex-row sm:items-start">
            <div className="flex min-w-0 flex-1 items-start gap-4">
              {avatar && <div className="shrink-0">{avatar}</div>}
              <div className="min-w-0">
                <div className="flex min-w-0 flex-wrap items-center gap-3">
                  <h1
                    id={headingId}
                    className="min-w-0 text-[28px] leading-tight font-semibold tracking-[-.035em] break-words sm:text-[34px]"
                  >
                    {title}
                  </h1>
                  {status}
                </div>
                {subtitle && (
                  <p className="mt-2 text-[13px] leading-6 break-words text-muted-foreground">
                    {subtitle}
                  </p>
                )}
              </div>
            </div>
            {actions && (
              <div className="flex flex-wrap items-center gap-2 sm:justify-end">
                {actions}
              </div>
            )}
          </div>
          {metadata.length > 0 && (
            <dl className="mt-6 grid min-w-0 grid-cols-2 gap-x-5 gap-y-5 border-t border-border/70 pt-5 lg:grid-cols-4">
              {metadata.map((item) => (
                <div key={item.id} className="min-w-0">
                  <dt className="flex items-center gap-2 text-[11px] text-muted-foreground">
                    {item.icon && (
                      <span aria-hidden="true" className="[&_svg]:size-3.5">
                        {item.icon}
                      </span>
                    )}
                    {item.label}
                  </dt>
                  <dd className="mt-2 text-sm font-semibold break-words">
                    {item.value ?? "—"}
                  </dd>
                </div>
              ))}
            </dl>
          )}
        </Card>
      )}

      {loading && hasContent && !missing && (
        <p role="status" className="text-xs text-muted-foreground">
          {copy.refreshing}
        </p>
      )}
      {problem && (
        <div className="grid gap-3">
          <Alert variant="destructive" title={copy.errorTitle}>
            {problem}
          </Alert>
          {onRetry && (
            <div>
              <Button
                type="button"
                variant="outline"
                onClick={() => void retry()}
                loading={retrying}
                disabled={loading}
              >
                <RefreshCw aria-hidden="true" />
                {copy.retry}
              </Button>
            </div>
          )}
        </div>
      )}
      {!initialLoading && !missing && (
        <>
          {tabs.length > 0 ? (
            <Tabs
              className="min-w-0 max-w-full"
              value={selectedTab}
              defaultValue={initialTab}
              onValueChange={(value) => onTabChange?.(String(value))}
            >
              <TabsList
                aria-label={copy.tabs}
                className="w-full justify-start sm:w-auto"
              >
                {tabs.map((tab) => (
                  <TabsTrigger
                    key={tab.value}
                    value={tab.value}
                    disabled={tab.disabled}
                  >
                    {tab.icon && <span aria-hidden="true">{tab.icon}</span>}
                    {tab.label}
                    {tab.count !== undefined && (
                      <span className="rounded-md bg-surface-subtle px-1.5 py-0.5 text-[10px] tabular-nums">
                        {tab.count}
                      </span>
                    )}
                  </TabsTrigger>
                ))}
              </TabsList>
              {tabs.map((tab) => (
                <TabsContent
                  key={tab.value}
                  value={tab.value}
                  keepMounted={tab.keepMounted ?? true}
                >
                  {tab.content}
                </TabsContent>
              ))}
            </Tabs>
          ) : (
            children
          )}
          {relatedContent}
        </>
      )}
    </section>
  );
}

import * as React from "react";
import { Info, CircleCheck, TriangleAlert } from "lucide-react";
import { cn } from "@/lib/utils";
export function Alert({
  title,
  children,
  variant = "info",
  className,
}: {
  title: string;
  children?: React.ReactNode;
  variant?: "info" | "success" | "warning" | "destructive";
  className?: string;
}) {
  const Icon =
    variant === "success"
      ? CircleCheck
      : variant === "warning" || variant === "destructive"
        ? TriangleAlert
        : Info;
  return (
    <div
      role={variant === "destructive" ? "alert" : "status"}
      className={cn(
        "flex gap-3 rounded-lg border p-4 text-xs",
        variant === "warning"
          ? "border-warning-foreground/20 bg-warning text-warning-foreground"
          : variant === "destructive"
            ? "border-destructive-foreground/20 bg-destructive text-destructive-foreground"
            : "border-primary/15 bg-accent text-accent-foreground",
        className,
      )}
    >
      <Icon className="mt-0.5 size-4 shrink-0" />
      <div>
        <p className="font-semibold">{title}</p>
        {children && <div className="mt-1 leading-relaxed">{children}</div>}
      </div>
    </div>
  );
}

"use client";
import * as React from "react";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";
import { LoaderCircle } from "lucide-react";
import { cn } from "@/lib/utils";
import "@/styles/effects.css";

export const buttonVariants = cva(
  "af-button af-control inline-flex shrink-0 items-center justify-center gap-2 whitespace-nowrap border border-transparent text-[13px] leading-5 font-semibold tracking-[-.01em] outline-none transition-[background-color,border-color,color,box-shadow,transform] duration-[var(--af-motion-fast,150ms)] active:scale-[.98] motion-reduce:transform-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:pointer-events-none disabled:opacity-45 data-disabled:pointer-events-none data-disabled:opacity-45 [@media(pointer:coarse)]:min-h-11 [@media(pointer:coarse)]:min-w-11 [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default:
          "af-button-primary bg-primary text-primary-foreground hover:bg-[color:var(--af-shade-primary,var(--primary-hover))]",
        outline:
          "af-button-outline border-border bg-surface text-foreground [background-image:none] hover:border-primary/40 hover:bg-[color:var(--af-shade-outline,var(--surface-subtle))]",
        secondary:
          "af-button-surface bg-accent text-accent-foreground [background-image:none] hover:bg-[color:var(--af-shade-surface,var(--accent))] hover:text-foreground",
        ghost:
          "bg-transparent text-muted-foreground hover:bg-surface-subtle hover:text-foreground",
        destructive:
          "af-button-destructive bg-destructive text-destructive-foreground [background-image:none] hover:bg-[color:var(--af-shade-destructive,var(--destructive))]",
        link: "af-hover-link bg-transparent text-primary underline underline-offset-4 hover:text-primary-hover",
      },
      size: {
        sm: "h-8 px-3",
        default: "h-[var(--af-control-height,40px)] px-4",
        lg: "h-12 px-6 text-sm",
        icon: "size-[var(--af-control-height,40px)]",
        "icon-sm": "size-8",
      },
      shape: {
        rounded: "rounded-[var(--radius-md,10px)]",
        pill: "rounded-full",
        square: "rounded-none",
      },
    },
    defaultVariants: { variant: "default", size: "default", shape: "rounded" },
  },
);
export type ButtonShape = "rounded" | "pill" | "square";
export type ButtonAppearance =
  "solid" | "soft" | "outline" | "glass" | "gradient";
const appearanceClasses: Record<ButtonAppearance, string> = {
  solid: "[background-image:none]",
  soft: "border-primary/25 bg-accent text-accent-foreground [background-image:none] hover:bg-[color:var(--af-shade-surface)] hover:text-foreground",
  outline:
    "border-primary/40 bg-surface text-foreground [background-image:none] hover:bg-[color:var(--af-shade-outline)] hover:text-foreground",
  glass:
    "border-primary/30 bg-[var(--af-glass-background)] text-foreground hover:bg-[var(--af-glass-background)] hover:text-foreground",
  gradient:
    "border-transparent bg-primary text-primary-foreground [background-image:var(--af-gradient-primary)] hover:bg-primary-hover hover:text-primary-foreground",
};
export type ButtonProps = Omit<
  React.ComponentProps<typeof ButtonPrimitive>,
  "className"
> &
  VariantProps<typeof buttonVariants> & {
    className?: string;
    loading?: boolean;
    appearance?: ButtonAppearance;
  };
export function Button({
  className,
  variant,
  size,
  shape,
  loading,
  appearance,
  children,
  disabled,
  focusableWhenDisabled,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  "aria-busy": ariaBusy,
  ...props
}: ButtonProps) {
  const labelId = React.useId();
  return (
    <ButtonPrimitive
      {...props}
      data-slot="button"
      data-variant={variant ?? "default"}
      data-size={size ?? "default"}
      data-shape={shape ?? "rounded"}
      data-appearance={appearance}
      className={cn(
        buttonVariants({ variant, size, shape }),
        appearance && `af-control-${appearance}`,
        appearance &&
          variant !== "destructive" &&
          appearanceClasses[appearance],
        className,
      )}
      disabled={disabled || loading}
      focusableWhenDisabled={focusableWhenDisabled ?? loading}
      aria-busy={loading || ariaBusy}
      aria-label={ariaLabel}
      aria-labelledby={
        ariaLabelledBy ?? (loading && !ariaLabel ? labelId : undefined)
      }
    >
      {loading && (
        <LoaderCircle
          className="motion-safe:animate-spin motion-reduce:animate-none [[data-motion-level=off]_&]:animate-none"
          aria-hidden="true"
        />
      )}
      <span id={labelId} className="contents">
        {children}
      </span>
    </ButtonPrimitive>
  );
}

